import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.CjPXnAcb.js";const k=JSON.parse('{"title":"命令行：学会用打字指挥电脑","description":"","frontmatter":{"title":"命令行：学会用打字指挥电脑"},"headers":[],"relativePath":"prereq/01-command-line.md","filePath":"prereq/01-command-line.md","lastUpdated":1789063242000}'),t={name:"prereq/01-command-line.md"};function l(p,s,r,o,d,h){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_01-·-命令行-学会用打字指挥电脑" tabindex="-1">01 · 命令行：学会用打字指挥电脑 <a class="header-anchor" href="#_01-·-命令行-学会用打字指挥电脑" aria-label="Permalink to &quot;01 · 命令行：学会用打字指挥电脑&quot;">​</a></h1><blockquote><p>一句话说清这课解决什么问题：让你不再怕那个黑乎乎的窗口，能站在正确的文件夹里敲出正确的命令——这是后面装工具、建网站、用 Git 的地基。</p></blockquote><h2 id="它是什么-大白话-一个生活比喻" tabindex="-1">它是什么？（大白话 + 一个生活比喻） <a class="header-anchor" href="#它是什么-大白话-一个生活比喻" aria-label="Permalink to &quot;它是什么？（大白话 + 一个生活比喻）&quot;">​</a></h2><p>平时你用电脑，是靠鼠标点图标、拖文件，这叫<strong>图形界面</strong>——像在餐厅看着菜单图片点菜。</p><p><strong>命令行</strong>则是另一个路子：你打开一个黑窗口，用打字的方式给电脑下指令，电脑打字回答你。它像去老字号饭馆直接跟掌柜喊话：「来二两牛肉面！」——不用看图，说一句话，事就办了。掌柜（电脑）话不多，但快、准，而且什么后厨的活（装软件、建文件、查状态）都能给你干。</p><p>在 Windows 上，这个黑窗口的程序叫 <strong>cmd</strong>（命令提示符）。本课所有命令都是 cmd 写法。</p><h2 id="为什么我们需要它-和你要做的-wiki-大模型项目挂钩" tabindex="-1">为什么我们需要它？（和你要做的 Wiki/大模型项目挂钩） <a class="header-anchor" href="#为什么我们需要它-和你要做的-wiki-大模型项目挂钩" aria-label="Permalink to &quot;为什么我们需要它？（和你要做的 Wiki/大模型项目挂钩）&quot;">​</a></h2><p>你正要搭的 Wiki 网站用 <strong>VitePress</strong>（一个把 Markdown 变成漂亮网站的工具），它没有「双击安装」这种东西——你得在命令行里敲一行命令启动它。后面学大模型应用开发，装库、跑脚本、调 API，几乎全在命令行里完成。</p><p>一句话：<strong>命令行是程序员的门厅，进屋（做项目）之前必须会开这扇门。</strong></p><h2 id="动手试一试-核心命令" tabindex="-1">动手试一试（核心命令） <a class="header-anchor" href="#动手试一试-核心命令" aria-label="Permalink to &quot;动手试一试（核心命令）&quot;">​</a></h2><p>先打开命令行：按 <code>Win + R</code>，输入 <code>cmd</code>，回车。弹出来的黑窗口就是命令行。</p><p>先理解一个概念：<strong>工作目录</strong>——你现在「站在」哪个文件夹里。命令行里每条命令都是对当前站着的文件夹说的，就像你跟掌柜说「看看货」时，掌柜只会看你手边这间仓库。</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\Users\\王奕博\\Desktop</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 走到桌面这个文件夹（cd = change directory，改变工作目录）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test-folder</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 新建一个叫 test-folder 的文件夹（md = make directory）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test-folder</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 走进刚建的文件夹</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">dir</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 列出当前文件夹里的内容（dir = directory），现在是空的</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ..</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 退回上一层（.. 就是「上一层文件夹」）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test-folder</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 删掉 test-folder（rd = remove directory，只能删空文件夹）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cls</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 清屏，把窗口里的字全擦掉，还你一片干净（cls = clear screen）</span></span></code></pre></div><p>试完你会发现：文件夹建了又删了，电脑毫发无损。命令行没那么可怕，敲错了顶多报个错，不会炸。</p><h2 id="常见报错与怎么读它" tabindex="-1">常见报错与怎么读它 <a class="header-anchor" href="#常见报错与怎么读它" aria-label="Permalink to &quot;常见报错与怎么读它&quot;">​</a></h2><p>真实案例（你以后几乎必遇到）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;git&#39; 不是内部或外部命令，也不是可运行的程序或批处理文件。</span></span></code></pre></div><p>怎么读这条报错？拆三段看：</p><ol><li><code>&#39;git&#39;</code>——引号里是<strong>你敲的那个词</strong>，说明电脑是对「git」这个词没反应，不是你敲错了格式。</li><li><code>不是内部或外部命令</code>——「内部命令」是 cmd 自带的（如 dir、cd），「外部命令」是装在电脑上的程序。这句的意思是：<strong>两拨人里都没找到叫 git 的</strong>。</li><li><code>也不是可运行的程序或批处理文件</code>——连当前文件夹里也没有 git.exe。</li></ol><p>为什么找不到？这里就要讲<strong>环境变量</strong>和 <strong>PATH</strong> 了。</p><p><strong>环境变量</strong>是 Windows 给系统和程序准备的一批「全局备忘」，其中最重要的一条就是 <strong>PATH</strong>：它是系统的一张「地址簿」，里面记着一串文件夹。你敲一个命令名（比如 <code>git</code>），系统就按地址簿<strong>挨个文件夹去找</strong>有没有 git.exe——找到了就运行，翻遍地址簿都没有，就报上面那个错。</p><p>所以这条报错的真正含义通常是：<strong>git 装了，但它的文件夹没写进 PATH 地址簿</strong>，或者压根没装。</p><p>解决办法有两条路：</p><ul><li>把 git 所在的文件夹加进 PATH（图形界面操作：设置 → 系统 → 关于 → 高级系统设置 → 环境变量，在 Path 里「新建」一条文件夹路径）。</li><li>或者干脆每次敲完整路径，比如 <code>C:\\工具\\git\\cmd\\git.exe --version</code>（直接报出完整门牌号，系统就不用查地址簿了）。</li></ul><p>顺便说下<strong>便携版</strong>：就是不用安装器、解压就能用的软件。好处是干净、随拷随走；代价是它不会在安装时自动「登记户口」（写进 PATH），所以经常要你手动加地址簿——这正是你遇到上面报错的原因。</p><h2 id="自测两题" tabindex="-1">自测两题 <a class="header-anchor" href="#自测两题" aria-label="Permalink to &quot;自测两题&quot;">​</a></h2><p><strong>第 1 题</strong>：<code>cd ..</code> 是干什么的？</p><details class="details custom-block"><summary>看答案</summary><p>退回上一层文件夹。比如你站在 <code>Desktop\\test-folder</code> 里，敲 <code>cd ..</code> 后就回到了 <code>Desktop</code>。可以连着用：<code>cd ..\\..</code> 是退两层。</p></details><p><strong>第 2 题</strong>：为什么敲 <code>git</code> 会报「不是内部或外部命令」，但敲 <code>dir</code> 就有反应？</p><details class="details custom-block"><summary>看答案</summary><p><code>dir</code> 是 cmd 的内部命令，自带随身，永远找得到；<code>git</code> 是外部程序，系统要去 PATH 地址簿里逐个文件夹找 git.exe。找不到就报这个错——说明 git 没装，或它的文件夹不在 PATH 里。</p></details><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p><a href="./02-node-and-npm.html">02 · Node.js 与 npm</a>——装好运行 VitePress 的「舞台」，学会用 npm 这个应用商店。</p>`,32)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
